    mapping(address => uint256) public portfolioAllocations;

    // Constructor to initialize token and portfolio allocations
constructor() ERC20("CARB Token", "CARB") Ownable(msg.sender) {
    // Mint 1 billion tokens to the sender (owner)
    _mint(msg.sender, 1_000_000_000 * 10 ** decimals()); // 1 billion tokens

    // Portfolio Allocation (Updated)
    portfolioTokens = [
        0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599, // WBTC
        0xae7ab96520DE3A18E5e111B5EaAb095312D7fE84, // stETH
        0x95aD61b0a150d79219dCF64E1E6Cc01f0B64C4cE, // SHIB
        0x7Fc66500c84A76Ad7e9c93437bFc5Ac33E2DDaE9, // AAVE
        0xB8c77482e45F1F44dE1745F52C74426C631bDD52, // BNB
        0x514910771AF9Ca656af840dff83E8264EcF986CA, // LINK
        0x455e53CBB86018Ac2B8092FdCd39d8444aFFC3F6, // POL
        0xB50721BCf8d664c30412Cfbc6cf7a15145234ad1  // ARB
    ];

    portfolioAllocations[portfolioTokens[0]] = 30; // WBTC (30%)
    portfolioAllocations[portfolioTokens[1]] = 20; // stETH (20%)
    portfolioAllocations[portfolioTokens[2]] = 15; // SHIB (15%)
    portfolioAllocations[portfolioTokens[3]] = 15; // AAVE (15%)
    portfolioAllocations[portfolioTokens[4]] = 5;  // BNB (5%)
    portfolioAllocations[portfolioTokens[5]] = 5;  // LINK (5%)
    portfolioAllocations[portfolioTokens[6]] = 5;  // POL (5%)
    portfolioAllocations[portfolioTokens[7]] = 5;  // ARB (5%)
}



    // Function to get the latest price from Chainlink
    function getLatestPrice(address _priceFeed) public view returns (int) {
        AggregatorV3Interface priceFeed = AggregatorV3Interface(_priceFeed);
        (, int price, , , ) = priceFeed.latestRoundData();
        return price;
    }

    // Function to get the price of WBTC in USD (WBTC/BTC * BTC/USD)
    function getWBTCPriceInUSD() public view returns (uint256) {
        int wbtcBtcPrice = getLatestPrice(address(WBTC_BTC));
        int btcUsdPrice = getLatestPrice(address(BTC_USD));
        uint256 wbtcPriceInUsd = uint256(wbtcBtcPrice) * uint256(btcUsdPrice) / 1e8; // Adjust for decimals
        return wbtcPriceInUsd;
    }

    // Function to get the price of SHIB in USD (SHIB/ETH * ETH/USD)
    function getSHIBPriceInUSD() public view returns (uint256) {
        int shibEthPrice = getLatestPrice(address(SHIB_ETH));
        int ethUsdPrice = getLatestPrice(address(ETH_USD));
        uint256 shibPriceInUsd = uint256(shibEthPrice) * uint256(ethUsdPrice) / 1e8; // Adjust for decimals
        return shibPriceInUsd;
    }

    // Function to calculate the portfolio value in USD based on Chainlink prices
    function calculatePortfolioValueInUSD() public view returns (uint256) {
        uint256 totalValue = 0;

        // Loop through portfolioTokens and calculate total value
        for (uint i = 0; i < portfolioTokens.length; i++) {
            address tokenAddress = portfolioTokens[i];
            uint256 allocation = portfolioAllocations[tokenAddress];
            if (allocation > 0) {
                uint256 tokenPriceInUSD = 0;
                
                // Calculate price for WBTC
                if (tokenAddress == portfolioTokens[0]) {
                    tokenPriceInUSD = getWBTCPriceInUSD();
                }
                // Calculate price for SHIB
                else if (tokenAddress == portfolioTokens[2]) {
                    tokenPriceInUSD = getSHIBPriceInUSD();
                }
                // For other tokens, just fetch their price from Chainlink
                else {
                    tokenPriceInUSD = uint256(getLatestPrice(tokenAddress));
                }

                // Add the value of this token to the total portfolio value
                totalValue += tokenPriceInUSD * allocation / 100;
            }
        }

        return totalValue;
    }

  // Function to handle management fee deduction (e.g., on a quarterly basis)
function deductManagementFee() public onlyOwner {
    uint256 portfolioValue = calculatePortfolioValueInUSD();
    uint256 managementFee = portfolioValue * 1 / 100;  // 1% management fee

    // Transfer fee to the specified address (e.g., the treasury or a specific address)
    address treasuryAddress = 0x785dcbeEA9a3601662EA57Cee5d9f7dcAAaD390A;
    payable(treasuryAddress).transfer(managementFee);
}


    // Function to withdraw tokens (e.g., for liquidity provision)
    function withdraw(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner(), amount);
    }
}
